const listBookSummariesByProject = `-- name: ListBookSummariesByProject :many
SELECT
  b.id,
  b.project_id,
  b.title,
  b.subtitle,
  b.cover_color,
  b."order",
  b.display_number,
  b.status,
  b.revision,
  b.deleted_at,
  b.purge_after,
  b.created_at,
  b.updated_at,
  COALESCE(cover.version, 0)::bigint AS cover_version,
  COALESCE(book_stats.chapter_count, 0)::integer AS chapter_count,
  COALESCE(book_stats.word_count, 0)::integer AS word_count,
  COALESCE(opening.text, '')::text AS opening
FROM books b
JOIN projects p ON p.id = b.project_id
LEFT JOIN LATERAL (
  SELECT artifact.version
  FROM book_cover_artifacts AS artifact
  WHERE artifact.book_id = b.id
    AND artifact.book_lifecycle_generation = b.lifecycle_generation
    AND artifact.state = 'active'
  LIMIT 1
) cover ON true
LEFT JOIN LATERAL (
  SELECT left(string_agg(btrim(first_paragraphs.plain_text), ' ' ORDER BY first_paragraphs."order"), 300) AS text
  FROM (
    SELECT c.id, c.revision
    FROM chapters c
    WHERE c.book_id = b.id
      AND c.deleted_at IS NULL
    ORDER BY c."order" ASC, c.id ASC
    LIMIT 1
  ) first_chapter
  JOIN LATERAL (
    SELECT cp.plain_text, cp."order"
    FROM chapter_paragraphs cp
    WHERE cp.chapter_id = first_chapter.id
      AND cp.revision = first_chapter.revision
      AND cp.variant = 'draft'
      AND btrim(cp.plain_text) <> ''
    ORDER BY cp."order" ASC
    LIMIT 4
  ) first_paragraphs ON true
) opening ON true
LEFT JOIN LATERAL (
  SELECT
    COUNT(c.id)::integer AS chapter_count,
    COALESCE(SUM(chapter_words.word_count), 0)::integer AS word_count
  FROM chapters c
  LEFT JOIN LATERAL (
    SELECT COALESCE(SUM(cp.word_count), 0)::integer AS word_count
    FROM chapter_paragraphs cp
    WHERE cp.chapter_id = c.id
      AND cp.revision = c.revision
      AND cp.variant = 'draft'
  ) chapter_words ON true
  WHERE c.book_id = b.id
    AND c.deleted_at IS NULL
) book_stats ON true
WHERE b.project_id = $1
  AND b.deleted_at IS NULL
  AND p.deleted_at IS NULL
  AND (NOT $2::boolean
    OR (b."order", b.id) > ($3::integer, $4::uuid))
ORDER BY b."order" ASC, b.id ASC
LIMIT $5
`

