const saveImportQueueVersion = `-- name: SaveImportQueueVersion :one
UPDATE import_queues
SET version = version + 1,
    status = CASE
      -- Every file is received — checked or not (specs/2026-11-11-ux7-upload.md UP1.2): a file that did not pass waits
      -- at its place and holds the others back no more.
      WHEN status = 'uploading' AND NOT EXISTS (
        SELECT 1
        FROM import_queue_items
        WHERE queue_id = import_queues.id
          AND project_id = import_queues.project_id
          AND (storage_key IS NULL OR preflight_status = 'uploading')
      ) THEN 'draft'
      ELSE status
    END,
    updated_at = $1
WHERE import_queues.id = $2
  AND import_queues.project_id = $3
  AND import_queues.version = $4
  AND import_queues.status IN ('uploading', 'draft')
RETURNING id, project_id, created_by_user_id, idempotency_key, request_fingerprint, status, version, created_at, updated_at, started_at, completed_at
`

type SaveImportQueueVersionParams struct {
	UpdatedAt       pgtype.Timestamptz `json:"updated_at"`
	QueueID         pgtype.UUID        `json:"queue_id"`
	ProjectID       pgtype.UUID        `json:"project_id"`
	ExpectedVersion int64              `json:"expected_version"`
}

func (q *Queries) SaveImportQueueVersion(ctx context.Context, arg SaveImportQueueVersionParams) (ImportQueue, error) {
	row := q.db.QueryRow(ctx, saveImportQueueVersion,
		arg.UpdatedAt,
		arg.QueueID,
		arg.ProjectID,
		arg.ExpectedVersion,
	)
	var i ImportQueue
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.CreatedByUserID,
		&i.IdempotencyKey,
		&i.RequestFingerprint,
		&i.Status,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.StartedAt,
		&i.CompletedAt,
	)
	return i, err
}

